  const w = ms.map((_, i) => Math.sin(Math.PI * (i + 0.5) / ms.length) * (1.35 - 0.7 * i / ms.length) + 0.3);
  const W = w.reduce((a, b) => a + b, 0);
  const amt = ms.map((_, i) => Math.floor(p.df_recommended_amount * w[i] / W / 1000) * 1000);
