chk("past: open projects in all three age bands", Object.values(out.s12_past.ages).every(n => n >= 2));
chk("past: last_followed_up == day of the latest message where messages exist", past_projects.every(p => { const d = [...past_project_updates.filter(m => m.past_project_id === p.id), ...past_pm_messages.filter(m => m.past_project_id === p.id)].map(m => m.created_at.slice(0, 10)).sort().at(-1); return !d || p.last_followed_up === d; }));
chk("past: exactly 1 unread project for the PMO (Unread filter) and 1 unread message in total (badge)", (() => { const seen = Object.fromEntries(past_chat_reads.map(x => [x.thread, x.read_at])); let total = 0; const projs = new Set();
  const add2 = (t, m) => { if (m.author_id === PMO.id) return; if (seen[t] && m.created_at <= seen[t]) return; total++; projs.add(m.past_project_id); };
  past_pm_messages.forEach(m => add2(`pm:${m.pm_user_id}`, m)); past_project_updates.forEach(m => add2(`project:${m.past_project_id}`, m)); return total === 1 && projs.size === 1; })());
chk("past: tagged PM-chat messages only tag that manager's own projects", past_pm_messages.every(m => !m.past_project_id || past_projects.find(p => p.id === m.past_project_id).pm_user_id === m.pm_user_id));
chk("past: closed rows read 'Closed/PCD Received'; released <= approved", past_projects.every(p => (p.status === "closed") === (p.reason_open === "Closed/PCD Received") && p.released_amount <= p.approved_amount));
chk("past-project age bands agree between the page (182/365 days) and the board report (30.44-day months)", (() => { const pa = { under6: 0, "6to12": 0, over12: 0, undated: 0 };
  pOpen.forEach(p => { const d2 = day(TODAY) - day(p.budget_release_date); pa[d2 > 365 ? "over12" : d2 > 182 ? "6to12" : "under6"]++; }); return JSON.stringify(pa) === JSON.stringify(oct.past.ages); })());
