chk("file paths are '<project_id>/<id>-<storage-safe name>' and unique", new Set(project_attachments.map(a => a.file_path)).size === project_attachments.length && project_attachments.every(a => a.file_path.startsWith(a.project_id + "/") && !/[\[\]]/.test(a.file_path)));
